/* Phase 3 additive patch: preserves Phase 2 lesson and expands practice to the full canonical bank. */
const PHASE3_EXTRA = [{"id": "A2", "room": "A", "difficulty": "core", "time": "2–3 min", "source": "AMO 2016 Primary 6 Q15", "type": "LIGHTLY ADAPTED", "q": {"en": "An ant starts at one vertex of a cube and must reach the opposite vertex, always moving along cube edges. How many shortest paths are possible?", "id": "Seekor semut mulai dari satu titik sudut kubus dan harus mencapai titik sudut yang berseberangan, hanya melalui rusuk-rusuk kubus. Ada berapa jalur terpendek yang mungkin?"}, "answers": ["6"], "trap": {"en": "Tracing routes randomly on the perspective cube.", "id": "Menelusuri jalur secara acak pada gambar perspektif kubus."}, "guide": {"en": "How many edge moves must every shortest route use?", "id": "Berapa banyak langkah rusuk yang selalu diperlukan oleh setiap jalur terpendek?"}, "hints": [{"en": "A shortest route changes each of the three cube directions exactly once.", "id": "Jalur terpendek berpindah satu kali pada masing-masing dari tiga arah kubus."}, {"en": "Replace the cube drawing with three move tokens: one move in each independent direction.", "id": "Ganti gambar kubus dengan tiga token langkah: satu langkah untuk tiap arah yang berbeda."}, {"en": "Now count the possible orders of those three different moves.", "id": "Sekarang hitung banyak urutan yang mungkin dari tiga langkah berbeda itu."}], "solution": {"en": "Every shortest path uses 3 edges, one in each cube direction. The three distinct moves can be ordered in 3×2×1=6 ways.", "id": "Setiap jalur terpendek memakai 3 rusuk, satu untuk tiap arah kubus. Tiga langkah berbeda itu dapat diurutkan dalam 3×2×1=6 cara."}, "transfer": {"en": "A spatial route can often be redrawn as an ordered sequence of required directions.", "id": "Jalur ruang sering lebih mudah jika diubah menjadi urutan langkah arah yang diperlukan."}, "visual": "cubePath"}, {"id": "A5", "room": "A", "difficulty": "core", "time": "1–2 min", "source": "AMO 2016 Primary 6 Q3", "type": "STRUCTURAL VARIANT", "q": {"en": "A 9×9 square contains a centered 8×8 square. What is the area inside the larger square but outside the smaller square?", "id": "Sebuah persegi 9×9 memuat persegi 8×8 di bagian tengah. Berapa luas daerah di dalam persegi besar tetapi di luar persegi kecil?"}, "answers": ["17"], "trap": {"en": "Subtracting the side lengths instead of the areas.", "id": "Mengurangkan panjang sisi, bukan luasnya."}, "guide": {"en": "What does the one-unit growth look like around the smaller square?", "id": "Seperti apa tambahan satu satuan di sekeliling persegi yang lebih kecil?"}, "hints": [{"en": "Think of the extra region as an L-shaped border.", "id": "Bayangkan daerah tambahan sebagai bingkai berbentuk L."}, {"en": "Split the border into one 9×1 strip and one 8×1 strip.", "id": "Pecah bingkai menjadi satu strip 9×1 dan satu strip 8×1."}, {"en": "Add the two strip areas.", "id": "Jumlahkan luas kedua strip itu."}], "solution": {"en": "The border is a 9×1 strip plus an 8×1 strip, so its area is 9+8=17 square units.", "id": "Bingkai terdiri dari strip 9×1 dan strip 8×1, jadi luasnya 9+8=17 satuan persegi."}, "transfer": {"en": "A difference of square areas can often be seen as a border instead of two separate calculations.", "id": "Selisih luas dua persegi sering lebih mudah dilihat sebagai bingkai, bukan dua hitungan terpisah."}, "visual": "nested9"}, {"id": "B5", "room": "B", "difficulty": "advanced", "time": "5–6 min", "source": "AMO 2017 Primary 6 Q23", "type": "RAW", "q": {"en": "A 5×5×5 cube has a 3×2×1 cuboid and a 5×1×1 cuboid removed from different corners, as in the source figure. What is the surface area of the remaining solid?", "id": "Sebuah kubus 5×5×5 dipotong pada dua sudut berbeda: satu bagian balok 3×2×1 dan satu bagian balok 5×1×1, seperti pada gambar sumber. Berapa luas permukaan bangun yang tersisa?"}, "answers": ["148"], "trap": {"en": "Subtracting removed outside faces without adding newly exposed faces.", "id": "Mengurangi bidang luar yang terpotong tanpa menambahkan bidang baru yang terbuka."}, "guide": {"en": "For each cut, which old outside faces disappear and which inside faces become exposed?", "id": "Untuk setiap potongan, bidang luar mana yang hilang dan bidang dalam mana yang menjadi terbuka?"}, "hints": [{"en": "Compare the new solid with the original cube rather than recounting every face.", "id": "Bandingkan bangun baru dengan kubus awal, jangan menghitung semua bidang dari nol."}, {"en": "For many corner cuts, lost outside area is replaced by equal newly exposed area.", "id": "Pada banyak potongan sudut, luas bidang luar yang hilang diganti oleh luas bidang baru yang sama."}, {"en": "The source geometry leaves only two 1×1 faces lost without equal replacement.", "id": "Pada geometri sumber, hanya dua bidang 1×1 yang hilang tanpa pengganti yang sama."}], "solution": {"en": "The original cube has surface area 150 cm². The cuts balance lost and newly exposed faces except for two 1×1 faces, so the final surface area is 148 cm².", "id": "Kubus awal memiliki luas permukaan 150 cm². Bidang yang hilang dan yang baru terbuka saling menyeimbangkan kecuali dua bidang 1×1, sehingga luas akhirnya 148 cm²."}, "transfer": {"en": "For notches, use a lost-face versus exposed-face ledger.", "id": "Untuk potongan pada bangun ruang, buat catatan bidang yang hilang dan bidang baru yang terbuka."}, "visual": "faceLedger"}, {"id": "B7", "room": "B", "difficulty": "core", "time": "2–3 min", "source": "AMO 2017 Primary 6 Q2", "type": "STRUCTURAL VARIANT", "q": {"en": "Two rectangles have areas 96 cm² and 54 cm². Their overlap has area 12 cm². What is the area covered by at least one rectangle?", "id": "Dua persegi panjang memiliki luas 96 cm² dan 54 cm². Daerah tumpang tindihnya 12 cm². Berapa luas daerah yang tertutup oleh sedikitnya satu persegi panjang?"}, "answers": ["138"], "trap": {"en": "Adding all three areas instead of removing the duplicate overlap.", "id": "Menjumlahkan ketiga luas tanpa mengoreksi daerah tumpang tindih yang terhitung dua kali."}, "guide": {"en": "Which part appears in both rectangle areas?", "id": "Bagian mana yang muncul dalam luas kedua persegi panjang?"}, "hints": [{"en": "Add the two rectangle areas first.", "id": "Jumlahkan luas kedua persegi panjang terlebih dahulu."}, {"en": "The overlap has now been counted twice.", "id": "Daerah tumpang tindih sekarang terhitung dua kali."}, {"en": "Remove one copy of the 12 cm² overlap.", "id": "Kurangi satu salinan daerah tumpang tindih 12 cm²."}], "solution": {"en": "96+54−12=138 cm².", "id": "96+54−12=138 cm²."}, "transfer": {"en": "Union area is A+B−overlap.", "id": "Luas gabungan adalah A+B−daerah tumpang tindih."}, "visual": "overlap96"}, {"id": "B8", "room": "B", "difficulty": "core", "time": "2–3 min", "source": "AMO 2016 Primary 6 Q10", "type": "STRUCTURAL VARIANT", "q": {"en": "Two identical 10×14 rectangles overlap in the same direction to form a 10×24 rectangle. What is the area of the overlap?", "id": "Dua persegi panjang identik 10×14 saling bertumpuk searah sehingga membentuk persegi panjang 10×24. Berapa luas daerah tumpang tindih?"}, "answers": ["40"], "trap": {"en": "Subtracting 24 from 14 instead of comparing both original lengths with the union.", "id": "Mengurangkan 24 dari 14, bukan membandingkan jumlah dua panjang awal dengan panjang gabungan."}, "guide": {"en": "How much length is counted twice?", "id": "Berapa panjang yang terhitung dua kali?"}, "hints": [{"en": "The two original lengths total 14+14.", "id": "Dua panjang awal berjumlah 14+14."}, {"en": "Compare 28 with the union length 24.", "id": "Bandingkan 28 dengan panjang gabungan 24."}, {"en": "The repeated length is 4; combine it with the common height 10.", "id": "Panjang yang berulang adalah 4; gabungkan dengan tinggi yang sama, 10."}], "solution": {"en": "Overlap length=28−24=4, so area=10×4=40.", "id": "Panjang tumpang tindih=28−24=4, jadi luas=10×4=40."}, "transfer": {"en": "Use duplicated length to recover overlap directly.", "id": "Gunakan panjang yang terhitung dua kali untuk menemukan tumpang tindih secara langsung."}, "visual": "overlap1024"}, {"id": "C5", "room": "C", "difficulty": "challenge", "time": "4–5 min", "source": "AMO 2018 Primary 6 Q18", "type": "LIGHTLY ADAPTED", "q": {"en": "A 24 m by 40 m floor is tiled using 2 m by 2 m square tiles and L-shaped tiles, each of area 4 m². Tiles may be rotated or flipped. What is the least number of tiles needed?", "id": "Lantai 24 m × 40 m dipasang ubin persegi 2 m × 2 m dan ubin berbentuk L, masing-masing berluas 4 m². Ubin boleh diputar atau dibalik. Berapa jumlah ubin paling sedikit?"}, "answers": ["240"], "trap": {"en": "Trying to optimize tile shape even though every tile covers the same area.", "id": "Mencari bentuk ubin terbaik padahal setiap ubin menutup luas yang sama."}, "guide": {"en": "What quantity is identical for both tile types?", "id": "Besaran apa yang sama untuk kedua jenis ubin?"}, "hints": [{"en": "Every tile covers 4 m².", "id": "Setiap ubin menutup 4 m²."}, {"en": "Find the floor area, then use it as a lower bound.", "id": "Cari luas lantai, lalu gunakan sebagai batas minimum."}, {"en": "Check that the lower bound is actually achievable, for example with square tiles.", "id": "Pastikan batas minimum itu benar-benar bisa dicapai, misalnya dengan ubin persegi."}], "solution": {"en": "The floor area is 960 m², so at least 960÷4=240 tiles are needed. A 24×40 floor can be tiled entirely by 2×2 squares, so 240 is achievable.", "id": "Luas lantai 960 m², jadi sedikitnya diperlukan 960÷4=240 ubin. Lantai 24×40 dapat ditutup seluruhnya dengan ubin 2×2, sehingga 240 memang dapat dicapai."}, "transfer": {"en": "Use preserved area for a lower bound, then prove the bound can be constructed.", "id": "Gunakan luas yang tetap sebagai batas minimum, lalu buktikan batas itu dapat diwujudkan."}, "visual": "tiles2440"}, {"id": "C6", "room": "C", "difficulty": "core", "time": "1–2 min", "source": "AMO 2017 Primary 6 Q15", "type": "STRUCTURAL VARIANT", "q": {"en": "A 4×4×4 cube is cut into two 4×4×2 halves and the halves are placed tightly side-by-side along a 4×2 face. What are the dimensions of the resulting cuboid?", "id": "Kubus 4×4×4 dipotong menjadi dua bagian 4×4×2, lalu kedua bagian diletakkan rapat berdampingan pada bidang 4×2. Berapa ukuran balok yang terbentuk?"}, "answers": ["8x4x2", "8×4×2", "4x8x2", "4×8×2", "8 4 2"], "trap": {"en": "Keeping every dimension at 4 instead of seeing which direction doubles.", "id": "Menganggap semua ukuran tetap 4 dan tidak melihat arah mana yang menjadi dua kali lebih panjang."}, "guide": {"en": "Which dimension extends when the two halves sit side-by-side?", "id": "Ukuran mana yang memanjang ketika kedua bagian diletakkan berdampingan?"}, "hints": [{"en": "Each half is 4×4×2.", "id": "Setiap bagian berukuran 4×4×2."}, {"en": "They touch along a 4×2 face.", "id": "Keduanya bersentuhan pada bidang 4×2."}, {"en": "The remaining 4-unit direction doubles while the other two dimensions stay fixed.", "id": "Arah 4 satuan yang tersisa menjadi dua kali, sedangkan dua ukuran lain tetap."}], "solution": {"en": "The resulting cuboid is 8×4×2.", "id": "Balok yang terbentuk berukuran 8×4×2."}, "transfer": {"en": "Reconstruct dimensions before calculating any derived quantity.", "id": "Susun ukuran bentuk akhir sebelum menghitung besaran turunannya."}, "visual": "reconstructDims"}, {"id": "D3", "room": "D", "difficulty": "core", "time": "1 min", "source": "AMO 2022 Grade 6 Mock-Up Q6", "type": "RAW", "q": {"en": "How many lines of symmetry does a general parallelogram have?", "id": "Berapa banyak garis simetri yang dimiliki jajargenjang umum?"}, "answers": ["0", "zero"], "trap": {"en": "Assuming diagonals are always lines of symmetry.", "id": "Menganggap diagonal selalu merupakan garis simetri."}, "guide": {"en": "Would reflecting a slanted parallelogram across a diagonal match every vertex?", "id": "Jika jajargenjang miring dicerminkan terhadap diagonal, apakah setiap titik sudut benar-benar berimpit?"}, "hints": [{"en": "Test a diagonal as a possible mirror line.", "id": "Uji salah satu diagonal sebagai calon garis cermin."}, {"en": "Also test the horizontal/vertical midpoint directions.", "id": "Uji juga arah mendatar atau tegak melalui titik tengah."}, {"en": "A general parallelogram is not automatically a rectangle or a rhombus.", "id": "Jajargenjang umum tidak selalu berupa persegi panjang atau belah ketupat."}], "solution": {"en": "A general parallelogram has rotational symmetry of order 2 but no reflection line, so it has 0 lines of symmetry.", "id": "Jajargenjang umum memiliki simetri putar tingkat 2 tetapi tidak memiliki garis simetri, jadi jumlahnya 0."}, "transfer": {"en": "Do not import symmetry properties from special cases.", "id": "Jangan memakai sifat simetri bangun khusus untuk semua jajargenjang."}, "visual": "parallelogram"}, {"id": "D4", "room": "D", "difficulty": "core", "time": "1 min", "source": "AMO 2018 Mock Test #1 Grade 6 Q2", "type": "LIGHTLY ADAPTED", "q": {"en": "How many lines of symmetry does a circle have?", "id": "Berapa banyak garis simetri yang dimiliki lingkaran?"}, "answers": ["infinitelymany", "infinite", "infinitely many", "takhingga", "tak terhingga"], "trap": {"en": "Choosing 4 because only a few familiar axes come to mind.", "id": "Menjawab 4 karena hanya membayangkan beberapa sumbu yang biasa digambar."}, "guide": {"en": "Could a mirror line through the center be drawn at another angle?", "id": "Bisakah garis cermin melalui pusat dibuat dengan kemiringan lain?"}, "hints": [{"en": "Any diameter splits the circle into matching halves.", "id": "Setiap diameter membagi lingkaran menjadi dua bagian yang berimpit."}, {"en": "There is no preferred direction for a diameter.", "id": "Tidak ada arah diameter yang istimewa."}, {"en": "Imagine rotating the mirror line continuously through the center.", "id": "Bayangkan garis cermin diputar terus-menerus melalui pusat."}], "solution": {"en": "Every line through the center is a line of symmetry, so there are infinitely many.", "id": "Setiap garis melalui pusat adalah garis simetri, jadi jumlahnya tak terhingga."}, "transfer": {"en": "Symmetry means all valid transformations, not only the axes that are easy to draw.", "id": "Simetri mencakup semua pencerminan yang valid, bukan hanya sumbu yang mudah digambar."}, "visual": "circle"}, {"id": "D6", "room": "D", "difficulty": "challenge", "time": "3–4 min", "source": "AMO 2017 Primary 6 Q13", "type": "STRUCTURAL VARIANT", "q": {"en": "Use the same configuration as AMO 2017 Q13, but let angle C=30° instead of 24°. Keep PQ=QR and BR=RC. Find angle QAC.", "id": "Gunakan konfigurasi yang sama seperti AMO 2017 Q13, tetapi sudut C=30° sebagai pengganti 24°. Tetap gunakan PQ=QR dan BR=RC. Tentukan sudut QAC."}, "answers": ["90"], "trap": {"en": "Starting the angle chase before marking both pairs of equal base angles.", "id": "Mulai menghitung sudut sebelum menandai dua pasang sudut alas yang sama."}, "guide": {"en": "What does BR=RC immediately tell you about triangle BRC?", "id": "Apa yang langsung dapat disimpulkan dari BR=RC pada segitiga BRC?"}, "hints": [{"en": "The two base angles of BRC are both 30°.", "id": "Dua sudut alas pada BRC masing-masing 30°."}, {"en": "Find the adjacent angle at R on the straight line, then use PQ=QR.", "id": "Cari sudut bersebelahan di R pada garis lurus, lalu gunakan PQ=QR."}, {"en": "After propagating the equal-angle information, complete triangle AQC.", "id": "Setelah hubungan sudut sama menyebar, selesaikan segitiga AQC."}], "solution": {"en": "BRC has base angles 30°, so angle BRC=120° and adjacent QRB=60°. PQR then has base angles 60°, making angle Q=60°. Thus QAC=180−60−30=90°.", "id": "BRC memiliki sudut alas 30°, jadi ∠BRC=120° dan sudut bersebelahan QRB=60°. PQR kemudian memiliki sudut alas 60°, sehingga sudut Q=60°. Maka QAC=180−60−30=90°."}, "transfer": {"en": "Propagate equal-angle structure before doing numerical calculation.", "id": "Sebarkan dulu hubungan sudut yang sama sebelum menghitung angka."}, "visual": "angle30"}, {"id": "E3", "room": "E", "difficulty": "challenge", "time": "3–4 min", "source": "AMO 2017 Primary 6 Q23", "type": "STRUCTURAL VARIANT", "q": {"en": "A 3×3×3 cube is made of unit cubes. Remove the unit cube at the center of one face (not on an edge). What is the new surface area?", "id": "Kubus 3×3×3 tersusun dari kubus satuan. Ambil satu kubus satuan di tengah salah satu sisi (bukan di rusuk). Berapa luas permukaan baru?"}, "answers": ["58"], "trap": {"en": "Assuming every removed cube leaves the surface area unchanged like a corner removal.", "id": "Menganggap setiap kubus yang diambil tidak mengubah luas permukaan seperti pada kasus sudut."}, "guide": {"en": "How many outside faces did the removed cube originally contribute?", "id": "Berapa bidang luar yang awalnya dimiliki kubus yang diambil?"}, "hints": [{"en": "It contributed only 1 outside face.", "id": "Kubus itu hanya menyumbang 1 bidang luar."}, {"en": "After removal, count the neighboring cube faces that become exposed.", "id": "Setelah diambil, hitung bidang kubus tetangga yang menjadi terbuka."}, {"en": "Five new faces become exposed, so compare +5 with the one face lost.", "id": "Lima bidang baru menjadi terbuka; bandingkan +5 dengan satu bidang yang hilang."}], "solution": {"en": "The original surface area is 54. Removing the face-center cube loses 1 outside face but exposes 5, a net gain of 4, so the new area is 58.", "id": "Luas permukaan awal 54. Mengambil kubus di tengah sisi menghilangkan 1 bidang luar tetapi membuka 5 bidang, perubahan bersih +4, sehingga luas baru 58."}, "transfer": {"en": "The location of a removed cube controls the balance of lost and exposed faces.", "id": "Posisi kubus yang diambil menentukan keseimbangan bidang yang hilang dan yang terbuka."}, "visual": "faceCenter"}, {"id": "E5", "room": "E", "difficulty": "challenge", "time": "3–4 min", "source": "AMO 2018 Mock Test #1 Grade 6 Q12", "type": "STRUCTURAL VARIANT", "q": {"en": "Six unit cubes form a 2×2 base layer. One extra cube is placed on top of each of two adjacent base cubes. What is the surface area?", "id": "Enam kubus satuan membentuk lapisan dasar 2×2. Satu kubus tambahan diletakkan di atas masing-masing dua kubus dasar yang bersebelahan. Berapa luas permukaannya?"}, "answers": ["22"], "trap": {"en": "Counting only the vertical contacts and forgetting contacts within each layer.", "id": "Menghitung hanya kontak vertikal dan melupakan kontak di dalam setiap lapisan."}, "guide": {"en": "Can you count all face-to-face contacts instead of visible faces?", "id": "Bisakah kamu menghitung semua bidang yang saling bersentuhan, bukan hanya bidang yang terlihat?"}, "hints": [{"en": "Six separate cubes have 36 faces.", "id": "Enam kubus terpisah memiliki 36 bidang."}, {"en": "The 2×2 base has 4 contacts; the two top cubes add two vertical contacts.", "id": "Dasar 2×2 memiliki 4 kontak; dua kubus atas menambah dua kontak vertikal."}, {"en": "The two top cubes also touch each other, giving one more contact.", "id": "Dua kubus atas juga saling bersentuhan, sehingga ada satu kontak lagi."}], "solution": {"en": "There are 7 contacts total, so 36−2×7=22 exposed unit faces.", "id": "Ada 7 kontak, jadi jumlah bidang satuan yang terbuka adalah 36−2×7=22."}, "transfer": {"en": "For cube stacks, count every contact plane once.", "id": "Untuk susunan kubus, hitung setiap bidang kontak tepat satu kali."}, "visual": "stack6"}, {"id": "E6", "room": "E", "difficulty": "core", "time": "2–3 min", "source": "AMO 2016 Primary 6 Q23", "type": "STRUCTURAL VARIANT", "q": {"en": "Two identical 4×4×2 bricks are glued along a 4×2 face. What is the exposed surface area?", "id": "Dua balok identik 4×4×2 direkatkan pada satu bidang 4×2. Berapa luas permukaan yang terbuka?"}, "answers": ["112"], "trap": {"en": "Subtracting the contact area only once.", "id": "Mengurangi luas bidang kontak hanya satu kali."}, "guide": {"en": "What becomes hidden on each brick?", "id": "Bidang apa yang menjadi tersembunyi pada masing-masing balok?"}, "hints": [{"en": "Find the surface area of one brick.", "id": "Cari luas permukaan satu balok."}, {"en": "Double it for two separate bricks.", "id": "Kalikan dua untuk dua balok terpisah."}, {"en": "The 4×2 contact face disappears from the exterior on both bricks.", "id": "Bidang kontak 4×2 hilang dari permukaan luar pada kedua balok."}], "solution": {"en": "One brick has surface area 64, so two have 128. Subtract two contact faces of area 8: 128−16=112.", "id": "Satu balok memiliki luas permukaan 64, jadi dua balok 128. Kurangi dua bidang kontak berluas 8: 128−16=112."}, "transfer": {"en": "Touching faces disappear from the exterior in pairs.", "id": "Bidang yang saling menempel hilang dari permukaan luar secara berpasangan."}, "visual": "glue442"}, {"id": "E7", "room": "E", "difficulty": "core", "time": "2–3 min", "source": "AMO 2018 Primary 6 Q18", "type": "STRUCTURAL VARIANT", "q": {"en": "An 8 m by 12 m floor is tiled using 2×2 square tiles and four-square-unit L-shaped tiles. What is the least number of tiles needed?", "id": "Lantai 8 m × 12 m dipasang ubin persegi 2×2 dan ubin berbentuk L yang masing-masing terdiri dari empat persegi satuan. Berapa jumlah ubin paling sedikit?"}, "answers": ["24"], "trap": {"en": "Thinking the L-shape can reduce the tile count below the area bound.", "id": "Mengira bentuk L dapat mengurangi jumlah ubin di bawah batas dari luas."}, "guide": {"en": "How much area does every tile cover?", "id": "Berapa luas yang ditutup oleh setiap ubin?"}, "hints": [{"en": "Each tile covers 4 m².", "id": "Setiap ubin menutup 4 m²."}, {"en": "The floor area is 96 m².", "id": "Luas lantai 96 m²."}, {"en": "Check that 24 square tiles can actually tile the floor.", "id": "Pastikan 24 ubin persegi benar-benar dapat menutup lantai."}], "solution": {"en": "At least 96÷4=24 tiles are needed, and 24 square tiles give an exact tiling.", "id": "Sedikitnya diperlukan 96÷4=24 ubin, dan 24 ubin persegi dapat menutup lantai tepat."}, "transfer": {"en": "Area gives a lower bound; construction verifies it is achievable.", "id": "Luas memberi batas minimum; susunan nyata membuktikan batas itu dapat dicapai."}, "visual": "tiles812"}, {"id": "F2", "room": "F", "difficulty": "challenge", "time": "3–4 min", "source": "AMO 2022 Grade 6 Mock-Up Q9", "type": "STRUCTURAL VARIANT", "q": {"en": "On a 4-by-3 cell grid, how many shortest paths go from the bottom-left corner to the top-right corner using only right and up moves?", "id": "Pada kisi 4×3 petak, berapa banyak jalur terpendek dari sudut kiri bawah ke sudut kanan atas jika hanya boleh bergerak ke kanan dan ke atas?"}, "answers": ["35"], "trap": {"en": "Multiplying 4×3 instead of organizing the required move sequence.", "id": "Mengalikan 4×3, bukan menyusun urutan langkah yang diperlukan."}, "guide": {"en": "What exact moves must every shortest route contain?", "id": "Langkah apa saja yang harus muncul pada setiap jalur terpendek?"}, "hints": [{"en": "Every shortest route needs 4 R moves and 3 U moves.", "id": "Setiap jalur terpendek memerlukan 4 langkah R dan 3 langkah U."}, {"en": "That gives 7 move positions in total.", "id": "Jadi ada 7 posisi langkah secara keseluruhan."}, {"en": "Choose which 3 of the 7 positions are U moves.", "id": "Pilih 3 dari 7 posisi untuk langkah U."}], "solution": {"en": "Choose the 3 up-move positions among 7 moves: 7 choose 3 =35.", "id": "Pilih 3 posisi langkah ke atas dari 7 langkah: hasilnya 35 jalur."}, "transfer": {"en": "Compress a path picture into an organized move sequence.", "id": "Ubah gambar jalur menjadi urutan langkah yang tersusun."}, "visual": "grid43"}, {"id": "F3", "room": "F", "difficulty": "challenge", "time": "3–4 min", "source": "AMO 2022 Grade 6 Mock-Up Q9", "type": "STRUCTURAL VARIANT", "q": {"en": "On a 2×2 cell grid, move from bottom-left to top-right using only right/up shortest moves. How many shortest paths avoid the central grid point?", "id": "Pada kisi 2×2 petak, bergerak dari kiri bawah ke kanan atas hanya dengan jalur terpendek ke kanan/atas. Berapa jalur terpendek yang menghindari titik tengah kisi?"}, "answers": ["2"], "trap": {"en": "Trying to draw only valid paths instead of using the complement.", "id": "Mencoba menggambar hanya jalur yang valid, bukan memakai komplemen."}, "guide": {"en": "Would total paths minus paths through the center be easier?", "id": "Apakah lebih mudah menghitung semua jalur lalu mengurangi jalur yang melalui titik tengah?"}, "hints": [{"en": "There are 6 shortest paths altogether.", "id": "Ada 6 jalur terpendek secara keseluruhan."}, {"en": "Count ways from start to center and from center to finish.", "id": "Hitung cara dari awal ke tengah dan dari tengah ke akhir."}, {"en": "There are 2 ways to reach the center and 2 ways to leave it.", "id": "Ada 2 cara mencapai tengah dan 2 cara meninggalkannya."}], "solution": {"en": "Four shortest paths pass through the center, so 6−4=2 avoid it.", "id": "Empat jalur terpendek melalui titik tengah, jadi 6−4=2 jalur menghindarinya."}, "transfer": {"en": "For “avoid” conditions, complement can simplify visual counting.", "id": "Untuk syarat “menghindari”, komplemen sering menyederhanakan hitung visual."}, "visual": "gridAvoid"}, {"id": "F5", "room": "F", "difficulty": "challenge", "time": "2–3 min", "source": "AMO 2018 Mock Test #1 Grade 6 Q4", "type": "STRUCTURAL VARIANT", "q": {"en": "How many squares of all sizes are in a 4×4 square grid?", "id": "Berapa banyak persegi dari semua ukuran dalam kisi persegi 4×4?"}, "answers": ["30"], "trap": {"en": "Stopping after the 1×1 and 2×2 squares.", "id": "Berhenti setelah menghitung persegi 1×1 dan 2×2."}, "guide": {"en": "Can you organize the count by square size?", "id": "Bisakah kamu menyusun hitungan berdasarkan ukuran persegi?"}, "hints": [{"en": "Count 1×1 squares first.", "id": "Hitung persegi 1×1 terlebih dahulu."}, {"en": "Then count 2×2, 3×3, and 4×4 squares.", "id": "Lalu hitung persegi 2×2, 3×3, dan 4×4."}, {"en": "The counts by size are 16, 9, 4, and 1.", "id": "Banyaknya berdasarkan ukuran adalah 16, 9, 4, dan 1."}], "solution": {"en": "16+9+4+1=30 squares.", "id": "16+9+4+1=30 persegi."}, "transfer": {"en": "A size table guarantees completeness better than visual scanning.", "id": "Tabel berdasarkan ukuran lebih menjamin kelengkapan daripada memindai gambar."}, "visual": "grid4"}, {"id": "F7", "room": "F", "difficulty": "challenge", "time": "3–4 min", "source": "AMO 2017 Primary 6 Q25", "type": "STRUCTURAL VARIANT", "q": {"en": "A 4×4 square grid has the top-left unit square shaded. How many squares of any size do NOT include the shaded square?", "id": "Kisi persegi 4×4 memiliki persegi satuan kiri atas yang diarsir. Berapa banyak persegi dari semua ukuran yang TIDAK memuat persegi diarsir itu?"}, "answers": ["26"], "trap": {"en": "Assuming the corner cell belongs to many placements of each size.", "id": "Menganggap sel sudut muncul dalam banyak posisi untuk setiap ukuran."}, "guide": {"en": "Would total squares minus squares containing the corner be simpler?", "id": "Apakah lebih mudah menghitung semua persegi lalu mengurangi persegi yang memuat sel sudut?"}, "hints": [{"en": "A 4×4 grid has 30 squares in total.", "id": "Kisi 4×4 memiliki 30 persegi seluruhnya."}, {"en": "A corner cell belongs to exactly one square of each possible size.", "id": "Sel sudut berada tepat pada satu persegi untuk setiap ukuran yang mungkin."}, {"en": "There are four possible sizes, so four squares contain the shaded corner cell.", "id": "Ada empat ukuran, jadi empat persegi memuat sel sudut yang diarsir."}], "solution": {"en": "30−4=26 squares do not include the shaded corner cell.", "id": "30−4=26 persegi tidak memuat sel sudut yang diarsir."}, "transfer": {"en": "Target position changes how many larger figures can contain it.", "id": "Posisi target mengubah banyak bangun yang dapat memuatnya."}, "visual": "gridCorner"}, {"id": "G1", "room": "G", "difficulty": "challenge", "time": "1–2 min", "source": "AMO 2017 Primary 6 Q12", "type": "RAW", "q": {"en": "A 4×4 square made of sixteen unit tiles is cut into exactly two pieces along tile edges. The original perimeter is 16 cm. What first visual move would best help maximize the combined perimeter?", "id": "Persegi 4×4 yang tersusun dari 16 ubin satuan dipotong menjadi tepat dua bagian sepanjang sisi ubin. Keliling awalnya 16 cm. Langkah visual pertama apa yang paling membantu untuk memaksimalkan jumlah keliling kedua bagian?"}, "answers": [], "trap": {"en": "Computing perimeters of random cuts.", "id": "Menghitung keliling dari potongan acak."}, "guide": {"en": "What new boundary is created by a cut?", "id": "Batas baru apa yang terbentuk setelah bangun dipotong?"}, "hints": [{"en": "A longer internal cut creates more new outside boundary.", "id": "Potongan dalam yang lebih panjang menghasilkan lebih banyak batas luar baru."}, {"en": "Focus on maximizing cut length rather than area.", "id": "Fokus pada memaksimalkan panjang potongan, bukan luas."}, {"en": "A zigzag cut through many tile edges can be stronger than a straight cut.", "id": "Potongan zigzag melalui banyak sisi ubin dapat lebih baik daripada potongan lurus."}], "solution": {"en": "A strong first move is to draw or seek the longest valid cut; every unit of cut appears twice in the separated perimeter.", "id": "Langkah pertama yang kuat adalah mencari atau menggambar potongan valid terpanjang; setiap satuan panjang potongan muncul dua kali pada keliling setelah dipisahkan."}, "transfer": {"en": "Translate a perimeter-change picture into old boundary plus twice the cut.", "id": "Ubah gambar perubahan keliling menjadi batas lama ditambah dua kali panjang potongan."}, "visual": "cutGrid", "mode": "moveOnly", "goodMoves": ["redraw", "split"]}, {"id": "G2", "room": "G", "difficulty": "core", "time": "1 min", "source": "AMO 2022 Grade 6 Mock-Up Q5", "type": "RAW", "q": {"en": "A 6-inch by 4-inch photo is enlarged without distortion so its new length is 12 inches. What visual move should come first before calculating the new width p?", "id": "Foto berukuran 6 inci × 4 inci diperbesar tanpa perubahan bentuk sehingga panjang barunya 12 inci. Langkah visual apa yang sebaiknya dilakukan sebelum menghitung lebar baru p?"}, "answers": [], "trap": {"en": "Adding 6 inches to both dimensions.", "id": "Menambahkan 6 inci pada kedua ukuran."}, "guide": {"en": "Which sides correspond before and after enlargement?", "id": "Sisi mana yang saling bersesuaian sebelum dan sesudah diperbesar?"}, "hints": [{"en": "Mark 6↔12 and 4↔p.", "id": "Tandai 6↔12 dan 4↔p."}, {"en": "The first pair shows the scale factor.", "id": "Pasangan pertama menunjukkan faktor skala."}, {"en": "Apply the same factor to the corresponding width.", "id": "Gunakan faktor yang sama pada lebar yang bersesuaian."}], "solution": {"en": "The strongest first move is to mark corresponding sides and the scale factor.", "id": "Langkah pertama terkuat adalah menandai sisi yang bersesuaian dan faktor skalanya."}, "transfer": {"en": "Mark correspondence before calculating a scale factor.", "id": "Tandai kesesuaian sisi sebelum menghitung faktor skala."}, "visual": "photo", "mode": "moveOnly", "goodMoves": ["mark"]}, {"id": "G3", "room": "G", "difficulty": "core", "time": "1–2 min", "source": "AMO 2022 Grade 6 Mock-Up Q3", "type": "RAW", "q": {"en": "A triangle has sides 12 cm, 35 cm, and 37 cm. What first visual/structural check should you make to classify it?", "id": "Sebuah segitiga memiliki sisi 12 cm, 35 cm, dan 37 cm. Pemeriksaan visual/struktural apa yang sebaiknya dilakukan terlebih dahulu untuk mengklasifikasikannya?"}, "answers": [], "trap": {"en": "Guessing from a rough sketch that is not to scale.", "id": "Menebak dari sketsa kasar yang tidak dibuat sesuai skala."}, "guide": {"en": "Which side should be treated differently?", "id": "Sisi mana yang perlu diperlakukan sebagai sisi utama?"}, "hints": [{"en": "Mark 37 as the longest side.", "id": "Tandai 37 sebagai sisi terpanjang."}, {"en": "Compare the square of the longest side with the sum of the squares of the other two.", "id": "Bandingkan kuadrat sisi terpanjang dengan jumlah kuadrat dua sisi lainnya."}, {"en": "Check whether 37² equals 35²+12².", "id": "Periksa apakah 37² sama dengan 35²+12²."}], "solution": {"en": "The strongest first move is to mark the longest side and test the Pythagorean relationship.", "id": "Langkah pertama terkuat adalah menandai sisi terpanjang lalu menguji hubungan Pythagoras."}, "transfer": {"en": "Structural length relationships are stronger than visual appearance.", "id": "Hubungan panjang yang pasti lebih kuat daripada tampilan sketsa."}, "visual": "triangle123537", "mode": "moveOnly", "goodMoves": ["mark"]}, {"id": "G4", "room": "G", "difficulty": "challenge", "time": "1–2 min", "source": "AMO 2016 Primary 6 Q17", "type": "STRUCTURAL VARIANT", "q": {"en": "Numbers 1 through 8 occupy a 3×3 frame with the center missing. You know the four outer row/column sums. Before solving individual cells, what would be the strongest first move?", "id": "Bilangan 1 sampai 8 mengisi bingkai 3×3 dengan bagian tengah kosong. Empat jumlah baris/kolom luar diketahui. Sebelum mencari nilai setiap sel, langkah pertama apa yang paling kuat?"}, "answers": [], "trap": {"en": "Starting to guess positions for 1 through 8.", "id": "Mulai menebak posisi bilangan 1 sampai 8."}, "guide": {"en": "What happens if you add all four line sums?", "id": "Apa yang terjadi jika keempat jumlah garis dijumlahkan?"}, "hints": [{"en": "Notice how often each position is counted.", "id": "Perhatikan berapa kali setiap posisi terhitung."}, {"en": "Corner entries are counted twice while edge-middle entries are counted once.", "id": "Posisi sudut terhitung dua kali, sedangkan posisi tengah sisi terhitung sekali."}, {"en": "Compare the line-sum total with 1+2+…+8.", "id": "Bandingkan total jumlah garis dengan 1+2+…+8."}], "solution": {"en": "A strong first move is to compare the sum of all line totals with the total of 1–8 and notice the corner double-counting.", "id": "Langkah pertama yang kuat adalah membandingkan jumlah semua garis dengan total 1–8 dan melihat bahwa sudut terhitung dua kali."}, "transfer": {"en": "Multiplicity of positions can reveal the target without filling every cell.", "id": "Banyaknya kemunculan setiap posisi dapat membuka target tanpa mengisi semua sel."}, "visual": "frame", "mode": "moveOnly", "goodMoves": ["count", "mark"]}, {"id": "G5", "room": "G", "difficulty": "challenge", "time": "1–2 min", "source": "AMO 2018 Primary 6 Q24", "type": "STRUCTURAL VARIANT", "q": {"en": "Numbers are placed around the perimeter of a triangle so each side has the same sum. If you add the three side sums, which positions should you notice are counted twice?", "id": "Bilangan ditempatkan di sepanjang keliling segitiga sehingga jumlah pada setiap sisi sama. Jika ketiga jumlah sisi dijumlahkan, posisi mana yang perlu diperhatikan karena terhitung dua kali?"}, "answers": [], "trap": {"en": "Treating every perimeter position as counted once.", "id": "Menganggap setiap posisi di keliling hanya terhitung sekali."}, "guide": {"en": "Which positions belong to two sides at the same time?", "id": "Posisi mana yang menjadi bagian dari dua sisi sekaligus?"}, "hints": [{"en": "Look where two sides meet.", "id": "Perhatikan tempat dua sisi bertemu."}, {"en": "Each vertex belongs to both adjacent side sums.", "id": "Setiap titik sudut masuk dalam jumlah dua sisi yang bersebelahan."}, {"en": "There are three such positions.", "id": "Ada tiga posisi seperti itu."}], "solution": {"en": "The three vertices are counted twice when the side sums are added.", "id": "Ketiga titik sudut terhitung dua kali saat jumlah ketiga sisi dijumlahkan."}, "transfer": {"en": "In visual sum problems, multiplicity can matter more than individual values.", "id": "Dalam soal jumlah visual, berapa kali suatu posisi terhitung bisa lebih penting daripada nilainya."}, "visual": "trianglePositions", "mode": "moveOnly", "goodMoves": ["mark", "count"]}, {"id": "M1", "room": "M", "difficulty": "core", "time": "2–3 min", "source": "AMO 2017 Primary 6 Q2", "type": "STRUCTURAL VARIANT", "q": {"en": "Two rectangles have areas 80 cm² and 56 cm². Their combined union area is 120 cm². What is the overlap area?", "id": "Dua persegi panjang memiliki luas 80 cm² dan 56 cm². Luas gabungannya 120 cm². Berapa luas daerah tumpang tindih?"}, "answers": ["16"], "trap": {"en": "Subtracting 120 from only one rectangle.", "id": "Mengurangkan 120 dari hanya salah satu persegi panjang."}, "guide": {"en": "What decomposition equation links the two original areas, overlap, and union?", "id": "Persamaan pemecahan apa yang menghubungkan dua luas awal, daerah tumpang tindih, dan luas gabungan?"}, "hints": [{"en": "Write A+B−overlap=union.", "id": "Tulis A+B−tumpang tindih=gabungan."}, {"en": "80+56 counts the overlap twice.", "id": "80+56 menghitung daerah tumpang tindih dua kali."}, {"en": "Compare 136 with the union 120.", "id": "Bandingkan 136 dengan luas gabungan 120."}], "solution": {"en": "80+56−overlap=120, so overlap=16 cm².", "id": "80+56−tumpang tindih=120, jadi luas tumpang tindih=16 cm²."}, "transfer": {"en": "The same decomposition relation works even when the unknown changes.", "id": "Hubungan pemecahan yang sama tetap berlaku ketika besaran yang dicari berubah."}, "visual": "mixedOverlap"}, {"id": "M2", "room": "M", "difficulty": "core", "time": "2 min", "source": "AMO 2016 Primary 6 Q3", "type": "STRUCTURAL VARIANT", "q": {"en": "A 12×12 square surrounds a centered 10×10 square. What is the area of the frame between them?", "id": "Persegi 12×12 mengelilingi persegi 10×10 di tengah. Berapa luas bingkai di antara keduanya?"}, "answers": ["44"], "trap": {"en": "Using 12−10=2 as an area.", "id": "Menggunakan 12−10=2 sebagai luas."}, "guide": {"en": "Would whole-area subtraction be cleaner than splitting the border here?", "id": "Apakah mengurangkan luas seluruh persegi lebih sederhana daripada memecah bingkai pada kasus ini?"}, "hints": [{"en": "Find the outer square area.", "id": "Cari luas persegi luar."}, {"en": "Find the inner square area.", "id": "Cari luas persegi dalam."}, {"en": "Subtract the inner area from the outer area.", "id": "Kurangi luas dalam dari luas luar."}], "solution": {"en": "12²−10²=144−100=44 square units.", "id": "12²−10²=144−100=44 satuan persegi."}, "transfer": {"en": "Choose between border decomposition and area subtraction based on which representation is cleaner.", "id": "Pilih antara memecah bingkai atau mengurangkan luas berdasarkan representasi yang paling sederhana."}, "visual": "nested12"}, {"id": "M3", "room": "M", "difficulty": "core", "time": "2 min", "source": "AMO 2022 Grade 6 Mock-Up Q11", "type": "STRUCTURAL VARIANT", "q": {"en": "A square is folded once vertically and once horizontally. A punch is made away from both fold lines. How many holes appear after complete unfolding?", "id": "Sebuah persegi dilipat sekali secara vertikal dan sekali secara horizontal. Satu lubang dibuat jauh dari kedua garis lipatan. Berapa banyak lubang setelah dibuka seluruhnya?"}, "answers": ["4"], "trap": {"en": "Doubling only once.", "id": "Menggandakan hanya sekali."}, "guide": {"en": "Which fold should be undone first?", "id": "Lipatan mana yang harus dibuka lebih dahulu?"}, "hints": [{"en": "Reverse the folds one at a time.", "id": "Buka lipatan satu per satu dengan urutan terbalik."}, {"en": "The first unfold reflects one hole into two.", "id": "Pembukaan pertama mencerminkan satu lubang menjadi dua."}, {"en": "The second unfold reflects both current holes.", "id": "Pembukaan kedua mencerminkan kedua lubang yang ada."}], "solution": {"en": "The hole count doubles from 1 to 2, then from 2 to 4.", "id": "Jumlah lubang bertambah dari 1 menjadi 2, lalu 2 menjadi 4."}, "transfer": {"en": "Reverse transformations sequentially rather than imagining the final state in one jump.", "id": "Balikkan transformasi secara bertahap, bukan membayangkan hasil akhir sekaligus."}, "visual": "twoFold"}, {"id": "M4", "room": "M", "difficulty": "challenge", "time": "3–4 min", "source": "AMO 2018 Mock Test #1 Grade 6 Q12", "type": "STRUCTURAL VARIANT", "q": {"en": "Six unit cubes form a row of four cubes, with one extra cube on top of each of the two middle cubes. What is the surface area?", "id": "Enam kubus satuan membentuk baris empat kubus, dengan satu kubus tambahan di atas masing-masing dua kubus tengah. Berapa luas permukaannya?"}, "answers": ["26"], "trap": {"en": "Counting visible faces from separate views and missing hidden contacts.", "id": "Menghitung bidang yang terlihat dari beberapa tampak dan melewatkan kontak tersembunyi."}, "guide": {"en": "Can you count cubes and contacts instead of visible faces?", "id": "Bisakah kamu menghitung jumlah kubus dan bidang kontak, bukan bidang yang tampak?"}, "hints": [{"en": "Six separate cubes have 36 faces.", "id": "Enam kubus terpisah memiliki 36 bidang."}, {"en": "The row of four cubes has 3 contacts.", "id": "Baris empat kubus memiliki 3 kontak."}, {"en": "The two upper cubes add 2 vertical contacts.", "id": "Dua kubus atas menambah 2 kontak vertikal."}], "solution": {"en": "There are 5 contacts, so surface area=36−2×5=26.", "id": "Ada 5 kontak, jadi luas permukaan=36−2×5=26."}, "transfer": {"en": "Use the contact method for arbitrary cube stacks.", "id": "Gunakan metode bidang kontak untuk susunan kubus apa pun."}, "visual": "stackRow"}, {"id": "M5", "room": "M", "difficulty": "core", "time": "2–3 min", "source": "AMO 2022 Grade 6 Mock-Up Q9", "type": "STRUCTURAL VARIANT", "q": {"en": "A shortest route on a grid requires exactly 3 moves right and 2 moves up. How many different shortest routes are possible?", "id": "Sebuah jalur terpendek pada kisi membutuhkan tepat 3 langkah ke kanan dan 2 langkah ke atas. Ada berapa jalur terpendek yang berbeda?"}, "answers": ["10"], "trap": {"en": "Multiplying 3×2.", "id": "Mengalikan 3×2."}, "guide": {"en": "Can the route be represented as an arrangement of move symbols?", "id": "Bisakah jalur ditulis sebagai susunan simbol langkah?"}, "hints": [{"en": "Every route is an order of R,R,R,U,U.", "id": "Setiap jalur adalah urutan R,R,R,U,U."}, {"en": "There are five move positions.", "id": "Ada lima posisi langkah."}, {"en": "Choose which two positions are occupied by U.", "id": "Pilih dua posisi yang ditempati U."}], "solution": {"en": "Choose 2 of the 5 positions for U, giving 10 routes.", "id": "Pilih 2 dari 5 posisi untuk U, sehingga ada 10 jalur."}, "transfer": {"en": "A path picture can often be compressed into an arrangement problem.", "id": "Gambar jalur sering dapat diubah menjadi soal menyusun urutan."}, "visual": "moveTokens"}, {"id": "M6", "room": "M", "difficulty": "challenge", "time": "3–4 min", "source": "AMO 2017 Primary 6 Q13", "type": "STRUCTURAL VARIANT", "q": {"en": "In the AMO 2017 Q13 configuration, keep PQ=QR and BR=RC but let angle C=20°. Find angle QAC.", "id": "Pada konfigurasi AMO 2017 Q13, tetap gunakan PQ=QR dan BR=RC tetapi ambil sudut C=20°. Tentukan sudut QAC."}, "answers": ["60"], "trap": {"en": "Not reusing equal-angle marks from the two isosceles triangles.", "id": "Tidak memanfaatkan kembali tanda sudut sama dari dua segitiga sama kaki."}, "guide": {"en": "Which equal angles are forced before any calculation?", "id": "Sudut mana yang harus sama sebelum melakukan hitungan apa pun?"}, "hints": [{"en": "Triangle BRC has two 20° base angles.", "id": "Segitiga BRC memiliki dua sudut alas 20°."}, {"en": "The adjacent angle at R then becomes 40°.", "id": "Sudut yang bersebelahan di R kemudian menjadi 40°."}, {"en": "Use PQ=QR to propagate that 40° into triangle PQR.", "id": "Gunakan PQ=QR untuk membawa sudut 40° itu ke segitiga PQR."}], "solution": {"en": "BRC gives adjacent QRB=40°. PQR then has base angles 40° and angle Q=100°. Thus QAC=180−100−20=60°.", "id": "Dari BRC diperoleh sudut bersebelahan QRB=40°. PQR kemudian memiliki sudut alas 40° dan sudut Q=100°. Maka QAC=180−100−20=60°."}, "transfer": {"en": "Propagate relationships before arithmetic.", "id": "Sebarkan hubungan pada gambar sebelum menghitung."}, "visual": "angle20"}, {"id": "M7", "room": "M", "difficulty": "challenge", "time": "3–4 min", "source": "AMO 2022 Grade 6 Mock-Up Q19", "type": "STRUCTURAL VARIANT", "q": {"en": "A solid 18×12×8 cuboid is melted and reshaped into a cube. Find the surface area of the cube.", "id": "Balok padat 18×12×8 dilelehkan lalu dibentuk menjadi kubus. Tentukan luas permukaan kubus tersebut."}, "answers": ["864"], "trap": {"en": "Using the original surface area instead of preserved volume.", "id": "Menggunakan luas permukaan awal, bukan volume yang tetap."}, "guide": {"en": "What survives when the same material is reshaped?", "id": "Apa yang tetap ketika bahan yang sama dibentuk ulang?"}, "hints": [{"en": "Preserve volume.", "id": "Pertahankan volume."}, {"en": "18×12×8=1728.", "id": "18×12×8=1728."}, {"en": "Recognize 1728 as 12³, then work with the new cube.", "id": "Kenali 1728 sebagai 12³, lalu gunakan kubus baru."}], "solution": {"en": "The cube side is 12, so surface area=6×12²=864.", "id": "Rusuk kubus 12, jadi luas permukaan=6×12²=864."}, "transfer": {"en": "Use the invariant first, then calculate on the reconstructed geometry.", "id": "Gunakan besaran yang tetap terlebih dahulu, lalu hitung pada bentuk baru."}, "visual": "reshape18128"}, {"id": "S1", "room": "S", "difficulty": "stretch", "time": "7–9 min", "source": "AMO 2017 Primary 6 Q25", "type": "RAW", "q": {"en": "A 7×7 chessboard has one shaded unit square in the source position (second column from the right, middle row). How many squares of any size do NOT include the shaded square?", "id": "Papan 7×7 memiliki satu persegi satuan diarsir pada posisi sumber (kolom kedua dari kanan, baris tengah). Berapa banyak persegi dari semua ukuran yang TIDAK memuat persegi diarsir itu?"}, "answers": ["110"], "trap": {"en": "Counting valid squares directly without organizing by size.", "id": "Menghitung persegi valid secara langsung tanpa menyusun berdasarkan ukuran."}, "guide": {"en": "Would total squares minus squares containing the shaded cell be easier?", "id": "Apakah lebih mudah menghitung semua persegi lalu mengurangi yang memuat sel diarsir?"}, "hints": [{"en": "Total squares in a 7×7 grid are 140.", "id": "Jumlah semua persegi dalam kisi 7×7 adalah 140."}, {"en": "Count squares containing the target by size.", "id": "Hitung persegi yang memuat target berdasarkan ukuran."}, {"en": "The source containing counts by size are 1,4,6,8,6,4,1.", "id": "Banyaknya menurut ukuran adalah 1,4,6,8,6,4,1."}], "solution": {"en": "There are 30 squares containing the target, so 140−30=110 do not.", "id": "Ada 30 persegi yang memuat target, jadi 140−30=110 tidak memuatnya."}, "transfer": {"en": "Complement plus size classification is stronger than visual scanning.", "id": "Komplemen ditambah pengelompokan ukuran lebih kuat daripada memindai gambar."}, "visual": "grid7"}, {"id": "S2", "room": "S", "difficulty": "stretch", "time": "5–7 min", "source": "AMO 2016 Primary 6 Q17", "type": "RAW", "q": {"en": "The numbers 1 through 8 fill a 3×3 frame with the center missing. The top row sums to 9, bottom row to 21, left column to 13, and right column to 15. What is the sum A+B+C+D of the four corner numbers?", "id": "Bilangan 1 sampai 8 mengisi bingkai 3×3 dengan bagian tengah kosong. Jumlah baris atas 9, baris bawah 21, kolom kiri 13, dan kolom kanan 15. Berapa jumlah A+B+C+D pada keempat sudut?"}, "answers": ["22"], "trap": {"en": "Trying to fill all eight positions.", "id": "Mencoba mengisi semua delapan posisi."}, "guide": {"en": "What does the sum of all four line totals count more than once?", "id": "Apa yang terhitung lebih dari sekali ketika keempat jumlah garis dijumlahkan?"}, "hints": [{"en": "The four line sums total 58.", "id": "Keempat jumlah garis totalnya 58."}, {"en": "The numbers 1 through 8 total 36.", "id": "Bilangan 1 sampai 8 berjumlah 36."}, {"en": "Only the corner entries are counted twice in the line-sum total.", "id": "Hanya posisi sudut yang terhitung dua kali dalam total jumlah garis."}], "solution": {"en": "The extra contribution is 58−36=22, exactly the sum of the four corners.", "id": "Kontribusi tambahan adalah 58−36=22, tepat sama dengan jumlah keempat sudut."}, "transfer": {"en": "Use multiplicity of positions instead of solving every cell.", "id": "Gunakan berapa kali suatu posisi terhitung, bukan mencari setiap sel."}, "visual": "frameFull"}, {"id": "S3", "room": "S", "difficulty": "stretch", "time": "6–8 min", "source": "AMO 2018 Primary 6 Q24", "type": "RAW", "q": {"en": "The numbers 1 through 12 are placed in the 12 circles around a triangle so that the sum along each side is the same. What is the largest possible common side sum?", "id": "Bilangan 1 sampai 12 ditempatkan pada 12 lingkaran di sekeliling segitiga sehingga jumlah pada setiap sisi sama. Berapa jumlah sisi sama terbesar yang mungkin?"}, "answers": ["37"], "trap": {"en": "Trying arrangements before understanding how the side sums count positions.", "id": "Mencoba susunan bilangan sebelum memahami berapa kali setiap posisi masuk ke jumlah sisi."}, "guide": {"en": "When the three side sums are added, which positions are counted twice?", "id": "Saat tiga jumlah sisi dijumlahkan, posisi mana yang terhitung dua kali?"}, "hints": [{"en": "The numbers 1 through 12 total 78.", "id": "Bilangan 1 sampai 12 berjumlah 78."}, {"en": "Non-vertex positions are counted once, while the three vertices are counted twice.", "id": "Posisi bukan sudut terhitung sekali, sedangkan tiga titik sudut terhitung dua kali."}, {"en": "To maximize the common side sum, maximize the extra vertex contribution.", "id": "Untuk memaksimalkan jumlah sisi yang sama, maksimalkan kontribusi tambahan dari titik sudut."}], "solution": {"en": "Put 10,11,12 at the vertices. Then 3S=78+33=111, so S=37.", "id": "Letakkan 10,11,12 di tiga titik sudut. Maka 3S=78+33=111, sehingga S=37."}, "transfer": {"en": "Count position multiplicity before optimizing values.", "id": "Hitung banyaknya kemunculan setiap posisi sebelum mengoptimalkan nilai."}, "visual": "triangle12"}];

