// Upgrade all Phase-2 problems to the same four-step support architecture without altering their mathematics.
const roomSupport={
 A:{en:['What relationship is difficult to see in the current picture?','Mark or redraw the feature named in the first hint.','Use the new representation to expose one intermediate relationship.'],id:['Hubungan apa yang sulit terlihat pada gambar sekarang?','Tandai atau gambar ulang bagian yang disebut pada petunjuk pertama.','Gunakan representasi baru untuk menemukan satu hubungan antara.']},
 B:{en:['Which region, edge, or face is being counted twice or hidden?','Separate the figure into familiar parts before calculating.','Write one overlap/contact relation, then stop before the final arithmetic.'],id:['Daerah, rusuk, atau bidang mana yang terhitung dua kali atau tersembunyi?','Pisahkan bangun menjadi bagian yang familiar sebelum menghitung.','Tulis satu hubungan tumpang tindih/kontak, lalu berhenti sebelum hitungan akhir.']},
 C:{en:['What are the pieces before and after the rearrangement?','Track which quantity or dimension survives the move.','Reconstruct the final shape before calculating the target.'],id:['Apa saja bagiannya sebelum dan sesudah disusun ulang?','Lacak besaran atau ukuran mana yang tetap selama perubahan.','Susun bentuk akhir sebelum menghitung target.']},
 D:{en:['Which reflection or equal-structure relation acts first?','Reverse only one reflection/fold or mark one symmetry relation.','Use that one mapping to create the next state, not the final state.'],id:['Pencerminan atau hubungan simetri mana yang bekerja terlebih dahulu?','Balikkan satu lipatan/pencerminan atau tandai satu hubungan simetri saja.','Gunakan satu pemetaan itu untuk membentuk keadaan berikutnya, bukan langsung hasil akhir.']},
 E:{en:['Which faces are touching, hidden, lost, or newly exposed?','Use a contact/face ledger rather than one camera view.','Compute one net face change before the final total.'],id:['Bidang mana yang bersentuhan, tersembunyi, hilang, atau baru terbuka?','Gunakan catatan kontak/bidang, bukan hanya satu tampak gambar.','Hitung satu perubahan bersih bidang sebelum total akhir.']},
 F:{en:['How can the visual cases be classified so none are missed?','Organize by size, move type, or complement.','Complete one row of the counting structure before totaling.'],id:['Bagaimana kasus visual dapat dikelompokkan agar tidak ada yang terlewat?','Susun berdasarkan ukuran, jenis langkah, atau komplemen.','Selesaikan satu bagian tabel hitung sebelum menjumlahkan semuanya.']}
};
bank.forEach(p=>{
 if(!p.guide){p.guide={en:'Before calculating, what visual change would expose the structure?',id:'Sebelum menghitung, perubahan visual apa yang dapat membuat strukturnya lebih jelas?'};}
 if(!p.hints){const rs=roomSupport[p.room]||roomSupport.A; p.hints=[p.hint||{en:rs.en[0],id:rs.id[0]},{en:rs.en[1],id:rs.id[1]},{en:rs.en[2],id:rs.id[2]}];}
 if(!p.transfer){p.transfer={en:'Return to the figure and name the visual structure that made the calculation shorter.',id:'Kembali ke gambar dan sebutkan struktur visual yang membuat hitungan lebih singkat.'};}
});

function p3LevelLabel(p){
 if(p.difficulty==='stretch')return t('stretch');
 return p.difficulty==='core'?t('core'):p.difficulty==='challenge'?t('challenge'):t('advanced');
}
function passes(p){return p.difficulty==='stretch'?true:p.difficulty===state.level}
function roomTitle(r){const map={
 A:{en:'A · VISUALIZE / REDRAW',id:'A · LIHAT ULANG / GAMBAR ULANG'},B:{en:'B · DECOMPOSE',id:'B · PECAH MENJADI BAGIAN'},C:{en:'C · RECONSTRUCT / REARRANGE',id:'C · SUSUN ULANG'},D:{en:'D · USE SYMMETRY',id:'D · GUNAKAN SIMETRI'},E:{en:'E · SPATIAL REASONING',id:'E · PENALARAN RUANG'},F:{en:'F · COUNT THROUGH GEOMETRY',id:'F · HITUNG MELALUI GEOMETRI'},G:{en:'G · WHICH VISUAL MOVE FIRST?',id:'G · LANGKAH VISUAL MANA DULU?'},M:{en:'MIXED VISUAL TAKES',id:'LATIHAN VISUAL CAMPURAN'},S:{en:'OPTIONAL STRETCH',id:'PENGAYAAN OPSIONAL'}};return i18n(map[r])}
function p3Pool(room=state.practiceRoom){return bank.filter(p=>p.room===room&&(room==='S'||passes(p))).sort((a,b)=>a.id.localeCompare(b.id,undefined,{numeric:true}))}
function currentProblem(){const pool=p3Pool();if(!pool.length)return null;state.practiceIndex=Math.max(0,Math.min(state.practiceIndex,pool.length-1));return pool[state.practiceIndex]}
function currentId(){return currentProblem()?.id||null}
function p3PushHistory(id){if(!id)return;const last=state.p3History[state.p3History.length-1];if(last&&last.id===id)return;state.p3History.push({id,room:state.practiceRoom,level:state.level});if(state.p3History.length>60)state.p3History.shift();}
function p3GoToId(id,push=true){const p=bank.find(x=>x.id===id);if(!p)return;if(push)p3PushHistory(currentId());state.practiceRoom=p.room;if(p.difficulty!=='stretch')state.level=p.difficulty;const pool=p3Pool(p.room);state.practiceIndex=Math.max(0,pool.findIndex(x=>x.id===id));render()}
function p3Evidence(id){return state.p3Solved[id]?.evidence||''}
function p3RecordCorrect(p){const attempts=state.p3Attempts[p.id]||0;const hintStep=state.p3HintStep[p.id]||0;const solution=!!state.p3Solution[p.id];let evidence=solution?'solutionSupported':attempts>1?'recovered':hintStep>0?'supported':'independent';state.p3Solved[p.id]={evidence,at:Date.now()};}
function p3Progress(level){const ids=Object.keys(state.p3Solved).filter(id=>bank.find(p=>p.id===id)?.difficulty===level);return ids.length}
function p3ProgressBar(){return `<div class="p3-progress"><span><b>${t('core')}</b> ${p3Progress('core')} ${t('solved')}</span><span><b>${t('challenge')}</b> ${p3Progress('challenge')} ${t('solved')}</span><span><b>${t('advanced')}</b> ${p3Progress('advanced')} ${t('solved')}</span><span><b>${t('stretch')}</b> ${p3Progress('stretch')} ${t('solved')}</span></div>`}

// ---------- Safe Phase-3 visuals: givens + neutral targets only ----------
function p3SvgWrap(body,alt){return `<svg viewBox="0 0 620 330" role="img" aria-label="${esc(alt)}">${body}</svg>`}
function p3Grid(cols,rows,shade=null,point=null){const x=80,y=40,w=360,h=240,cw=w/cols,ch=h/rows;let body='';if(shade){body+=`<rect x="${x+shade.c*cw}" y="${y+shade.r*ch}" width="${cw}" height="${ch}" fill="#f1d5df"/>`}for(let i=0;i<=cols;i++)body+=`<line x1="${x+i*cw}" y1="${y}" x2="${x+i*cw}" y2="${y+h}" stroke="#78909a"/>`;for(let j=0;j<=rows;j++)body+=`<line x1="${x}" y1="${y+j*ch}" x2="${x+w}" y2="${y+j*ch}" stroke="#78909a"/>`;if(point)body+=`<circle cx="${x+point.c*cw}" cy="${y+point.r*ch}" r="8" fill="#fff" stroke="#d9467d" stroke-width="4"/><text x="${x+point.c*cw+14}" y="${y+point.r*ch-10}" class="given">${state.lang==='en'?'avoid':'hindari'}</text>`;return p3SvgWrap(body,state.lang==='en'?'Neutral grid showing only the given structure.':'Kisi netral yang hanya menampilkan informasi yang diberikan.')}
function cubePathSVG(){return p3SvgWrap(`<g fill="none" stroke="#31596b" stroke-width="3"><rect x="150" y="90" width="190" height="150"/><rect x="245" y="45" width="190" height="150"/><line x1="150" y1="90" x2="245" y2="45"/><line x1="340" y1="90" x2="435" y2="45"/><line x1="340" y1="240" x2="435" y2="195"/><line x1="150" y1="240" x2="245" y2="195"/></g><circle cx="150" cy="240" r="8" fill="#278a93"/><circle cx="435" cy="45" r="8" fill="#d9467d"/><text x="110" y="265" class="given">${state.lang==='en'?'START':'MULAI'}</text><text x="447" y="42" class="given">${state.lang==='en'?'OPPOSITE':'BERSEBERANGAN'}</text>`,state.lang==='en'?'Wireframe cube with start and opposite target vertices. No path is highlighted.':'Kubus rangka dengan titik awal dan target berseberangan. Tidak ada jalur yang disorot.')}
function faceLedgerSVG(){return p3SvgWrap(`<rect x="70" y="70" width="190" height="170" rx="14" fill="#e9f6fa" stroke="#31596b" stroke-width="3"/><rect x="360" y="70" width="190" height="170" rx="14" fill="#f7eef2" stroke="#a94a6f" stroke-width="3"/><text x="165" y="120" text-anchor="middle" class="given">${state.lang==='en'?'LOST OUTSIDE':'BIDANG LUAR HILANG'}</text><text x="455" y="120" text-anchor="middle" class="given">${state.lang==='en'?'NEWLY EXPOSED':'BARU TERBUKA'}</text><text x="165" y="180" text-anchor="middle" class="target">?</text><text x="455" y="180" text-anchor="middle" class="target">?</text><path d="M275 155 H335" stroke="#6d49a8" stroke-width="4" marker-end="url(#a)"/>`,state.lang==='en'?'Neutral lost-versus-exposed face ledger. No solved areas are shown.':'Catatan netral bidang hilang dan bidang baru terbuka. Tidak ada luas hasil yang ditampilkan.')}
function overlapP3(a,b,u,labelA,labelB){return p3SvgWrap(`<rect x="80" y="95" width="300" height="120" fill="#dff1f4" stroke="#31596b" stroke-width="3"/><rect x="250" y="95" width="290" height="120" fill="#f1ebfb" fill-opacity=".82" stroke="#6d49a8" stroke-width="3"/><rect x="250" y="95" width="130" height="120" fill="#fff0ce" fill-opacity=".88"/><text x="160" y="80" class="given">${esc(labelA||a)}</text><text x="450" y="80" class="given">${esc(labelB||b)}</text><text x="315" y="163" text-anchor="middle" class="target">?</text>${u?`<text x="310" y="260" text-anchor="middle" class="given">${esc(u)}</text>`:''}`,state.lang==='en'?'Two overlapping rectangles with only given values and an unknown overlap marker.':'Dua persegi panjang bertumpuk dengan hanya nilai yang diberikan dan penanda tumpang tindih yang belum diketahui.')}
function tilesSVG(big){return p3SvgWrap(`<rect x="60" y="55" width="250" height="170" fill="#fbfdfd" stroke="#31596b" stroke-width="3"/><text x="185" y="45" text-anchor="middle" class="given">${big}</text><g transform="translate(390 80)" fill="#fff0ce" stroke="#8b6508" stroke-width="2"><rect x="0" y="0" width="38" height="38"/><rect x="0" y="38" width="38" height="38"/><rect x="0" y="76" width="38" height="38"/><rect x="38" y="76" width="38" height="38"/></g><text x="430" y="220" text-anchor="middle" class="given">${state.lang==='en'?'each tile area = 4':'luas tiap ubin = 4'}</text>`,state.lang==='en'?'Floor rectangle and the two equal-area tile types. No tile count is shown.':'Persegi panjang lantai dan dua jenis ubin dengan luas sama. Jumlah ubin belum ditampilkan.')}
function reconstructDimsSVG(){return p3SvgWrap(`<g fill="#e9f6fa" stroke="#31596b" stroke-width="3"><rect x="80" y="100" width="180" height="110" rx="4"/><rect x="360" y="100" width="180" height="110" rx="4"/></g><text x="170" y="90" text-anchor="middle" class="given">4×4×2</text><text x="450" y="90" text-anchor="middle" class="given">4×4×2</text><path d="M275 155 H345" stroke="#6d49a8" stroke-width="4" stroke-dasharray="8 6"/><text x="310" y="260" text-anchor="middle" class="target">${state.lang==='en'?'final dimensions = ?':'ukuran akhir = ?'}</text>`,state.lang==='en'?'Two 4 by 4 by 2 halves shown before combining; final dimensions are unknown.':'Dua bagian 4×4×2 sebelum digabungkan; ukuran akhir belum diketahui.')}
function parallelogramSVG(){return p3SvgWrap(`<polygon points="150,220 390,220 480,90 240,90" fill="#e9f6fa" stroke="#31596b" stroke-width="3"/><line x1="150" y1="220" x2="480" y2="90" stroke="#8aa0aa" stroke-dasharray="8 6"/><line x1="390" y1="220" x2="240" y2="90" stroke="#8aa0aa" stroke-dasharray="8 6"/><text x="315" y="280" text-anchor="middle" class="target">${state.lang==='en'?'mirror lines?':'garis simetri?'}</text>`,state.lang==='en'?'General slanted parallelogram with neutral candidate diagonals.':'Jajargenjang miring umum dengan diagonal kandidat netral.')}
function circleSVG(){return p3SvgWrap(`<circle cx="310" cy="155" r="105" fill="#fbfdfd" stroke="#31596b" stroke-width="3"/><circle cx="310" cy="155" r="5" fill="#31596b"/><text x="310" y="295" text-anchor="middle" class="target">${state.lang==='en'?'How many mirror lines?':'Berapa garis simetri?'}</text>`,state.lang==='en'?'Circle with center marked and no symmetry axes drawn.':'Lingkaran dengan pusat ditandai tanpa garis simetri yang digambar.')}
function angleChainSVG(c){return `<div class="visual-stage">${angleSVG().replace(/24°/g,c+'°').replace(/24 derajat/g,c+' derajat').replace(/given equal-side marks and 24 degree angle/g,'given equal-side marks and '+c+' degree angle')}</div>`}
function faceCenterSVG(){return p3SvgWrap(`<rect x="165" y="45" width="270" height="270" fill="#fbfdfd" stroke="#31596b" stroke-width="3"/>${[1,2].map(i=>`<line x1="${165+i*90}" y1="45" x2="${165+i*90}" y2="315" stroke="#78909a"/><line x1="165" y1="${45+i*90}" x2="435" y2="${45+i*90}" stroke="#78909a"/>`).join('')}<rect x="255" y="135" width="90" height="90" fill="#f1d5df" stroke="#d9467d" stroke-width="2" stroke-dasharray="8 5"/><text x="300" y="190" text-anchor="middle" class="given">${state.lang==='en'?'remove':'ambil'}</text>`,state.lang==='en'?'Front face of a 3 by 3 by 3 cube with the face-center unit cube marked for removal.':'Sisi depan kubus 3×3×3 dengan kubus satuan di tengah sisi ditandai untuk diambil.')}
function stack6SVG(kind){if(kind==='row')return p3SvgWrap(`<g fill="#dff1f4" stroke="#31596b" stroke-width="2.5">${[90,170,250,330].map(x=>`<rect x="${x}" y="170" width="80" height="80"/>`).join('')}<rect x="170" y="90" width="80" height="80"/><rect x="250" y="90" width="80" height="80"/></g>`,state.lang==='en'?'Schematic row of four unit cubes with one cube above each middle cube. Contacts are not counted.':'Skema empat kubus berjajar dengan satu kubus di atas masing-masing dua kubus tengah. Kontak belum dihitung.');return p3SvgWrap(`<g fill="#dff1f4" stroke="#31596b" stroke-width="2.5"><rect x="150" y="170" width="80" height="80"/><rect x="230" y="170" width="80" height="80"/><rect x="150" y="90" width="80" height="80"/><rect x="230" y="90" width="80" height="80"/><rect x="150" y="10" width="80" height="80"/><rect x="230" y="10" width="80" height="80"/></g>`,state.lang==='en'?'Schematic six-cube stack with a 2 by 2 base relation. Contact count is hidden.':'Skema susunan enam kubus dengan hubungan dasar 2×2. Jumlah kontak disembunyikan.')}
function glue442SVG(){return p3SvgWrap(`<rect x="90" y="105" width="190" height="110" fill="#e9f6fa" stroke="#31596b" stroke-width="3"/><rect x="340" y="105" width="190" height="110" fill="#f1ebfb" stroke="#6d49a8" stroke-width="3"/><rect x="280" y="130" width="60" height="60" fill="#fff0ce" stroke="#8b6508" stroke-width="2" stroke-dasharray="6 4"/><text x="310" y="125" text-anchor="middle" class="given">4×2 ${state.lang==='en'?'contact':'kontak'}</text><text x="185" y="90" text-anchor="middle" class="given">4×4×2</text><text x="435" y="90" text-anchor="middle" class="given">4×4×2</text>`,state.lang==='en'?'Two 4 by 4 by 2 bricks with the given 4 by 2 contact face marked. Exposed area is not shown.':'Dua balok 4×4×2 dengan bidang kontak 4×2 yang diberikan. Luas terbuka belum ditampilkan.')}
function cutGridSVG(){return p3Grid(4,4)}
function photoSVG(){return p3SvgWrap(`<rect x="80" y="80" width="210" height="140" fill="#e9f6fa" stroke="#31596b" stroke-width="3"/><rect x="360" y="60" width="190" height="180" fill="#f1ebfb" stroke="#6d49a8" stroke-width="3"/><text x="185" y="70" text-anchor="middle" class="given">6</text><text x="65" y="155" class="given">4</text><text x="455" y="50" text-anchor="middle" class="given">12</text><text x="555" y="155" class="target">p</text>`,state.lang==='en'?'Original and enlarged rectangles with corresponding given length labels; unknown width p remains unknown.':'Persegi panjang awal dan hasil pembesaran dengan panjang yang diketahui; lebar p tetap belum diketahui.')}
function triangleSidesSVG(){return p3SvgWrap(`<polygon points="100,250 500,250 440,75" fill="#fbfdfd" stroke="#31596b" stroke-width="3"/><text x="300" y="280" text-anchor="middle" class="given">35</text><text x="475" y="160" class="given">12</text><text x="220" y="145" class="given">37</text><text x="310" y="315" text-anchor="middle" class="muted">${state.lang==='en'?'not to scale':'gambar tidak sesuai skala'}</text>`,state.lang==='en'?'Triangle labelled 12, 35, and 37, explicitly not to scale.':'Segitiga berlabel 12, 35, dan 37, dengan keterangan gambar tidak sesuai skala.')}
function frameSVG(full=false){return p3SvgWrap(`<g fill="none" stroke="#31596b" stroke-width="3"><rect x="190" y="60" width="240" height="240"/><rect x="270" y="140" width="80" height="80" fill="#fff" stroke-dasharray="8 6"/></g><text x="310" y="45" text-anchor="middle" class="given">${full?'top = 9':'top = ?'}</text><text x="310" y="325" text-anchor="middle" class="given">${full?'bottom = 21':'bottom = 21'}</text><text x="165" y="185" class="given">${full?'left = 13':'left = 13'}</text><text x="440" y="185" class="given">${full?'right = 15':'right = 15'}</text>${['A','B','C','D'].map((z,i)=>`<text x="${i%2?390:230}" y="${i<2?115:275}" text-anchor="middle" class="target">${z}</text>`).join('')}`,state.lang==='en'?'Three by three frame with center missing and given outer line sums. Individual values are not filled.':'Bingkai 3×3 dengan bagian tengah kosong dan jumlah garis luar yang diberikan. Nilai setiap posisi belum diisi.')}
function trianglePositionsSVG(){let pts=[];const A=[310,45],B=[90,275],C=[530,275];function interp(P,Q,t){return [P[0]+(Q[0]-P[0])*t,P[1]+(Q[1]-P[1])*t]}for(const [P,Q] of [[A,B],[A,C],[B,C]])for(let i=0;i<4;i++)pts.push(interp(P,Q,i/3));const uniq=[];pts.forEach(p=>{if(!uniq.some(q=>Math.hypot(q[0]-p[0],q[1]-p[1])<2))uniq.push(p)});while(uniq.length<12)uniq.push([310,275]);return p3SvgWrap(`<polygon points="310,45 90,275 530,275" fill="none" stroke="#31596b" stroke-width="3"/>${uniq.slice(0,12).map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="10" fill="#fff" stroke="#6d49a8" stroke-width="2"/>`).join('')}`,state.lang==='en'?'Triangle perimeter positions shown as empty circles; no values are prefilled.':'Posisi pada keliling segitiga ditampilkan sebagai lingkaran kosong; tidak ada nilai yang diisikan sebelumnya.')}
function moveTokensSVG(){return p3SvgWrap(`<g>${['?','?','?','?','?'].map((z,i)=>`<rect x="${85+i*95}" y="105" width="70" height="70" rx="12" fill="#f1ebfb" stroke="#6d49a8" stroke-width="2"/><text x="${120+i*95}" y="150" text-anchor="middle" class="target">${z}</text>`).join('')}</g><text x="310" y="225" text-anchor="middle" class="given">3 R · 2 U</text>`,state.lang==='en'?'Five blank move positions with the given multiset three R and two U.':'Lima posisi langkah kosong dengan informasi tiga R dan dua U.')}
function reshapeP3SVG(label){return p3SvgWrap(`<rect x="70" y="85" width="240" height="145" fill="#e9f6fa" stroke="#31596b" stroke-width="3"/><text x="190" y="75" text-anchor="middle" class="given">${label}</text><path d="M325 158 H385" stroke="#6d49a8" stroke-width="4"/><polygon points="385,158 370,148 370,168" fill="#6d49a8"/><rect x="420" y="90" width="130" height="130" fill="#f1ebfb" stroke="#6d49a8" stroke-width="3"/><text x="485" y="160" text-anchor="middle" class="target">?</text>`,state.lang==='en'?'Cuboid reshaped into an unknown cube; only original dimensions are given.':'Balok dibentuk ulang menjadi kubus yang ukurannya belum diketahui; hanya ukuran awal yang diberikan.')}

const _phase2ProblemVisual=problemVisual;
problemVisual=function(p){
 const v=p.visual;
 if(v==='cubePath')return `<div class="visual-stage">${cubePathSVG()}</div>`;
 if(v==='nested9')return `<div class="visual-stage">${nestedSquareSVG(9,8)}</div>`;
 if(v==='faceLedger')return `<div class="visual-stage">${faceLedgerSVG()}</div>`;
 if(v==='overlap96')return `<div class="visual-stage">${overlapP3('96 cm²','54 cm²','overlap = 12 cm²','96 cm²','54 cm²')}</div>`;
 if(v==='overlap1024')return `<div class="visual-stage">${overlapP3('10×14','10×14',state.lang==='en'?'union = 10×24':'gabungan = 10×24','10×14','10×14')}</div>`;
 if(v==='tiles2440')return `<div class="visual-stage">${tilesSVG('24 m × 40 m')}</div>`;
 if(v==='reconstructDims')return `<div class="visual-stage">${reconstructDimsSVG()}</div>`;
 if(v==='parallelogram')return `<div class="visual-stage">${parallelogramSVG()}</div>`;
 if(v==='circle')return `<div class="visual-stage">${circleSVG()}</div>`;
 if(v==='angle30')return angleChainSVG(30);
 if(v==='faceCenter')return `<div class="visual-stage">${faceCenterSVG()}</div>`;
 if(v==='stack6')return `<div class="visual-stage">${stack6SVG('base')}</div>`;
 if(v==='glue442')return `<div class="visual-stage">${glue442SVG()}</div>`;
 if(v==='tiles812')return `<div class="visual-stage">${tilesSVG('8 m × 12 m')}</div>`;
 if(v==='grid43')return `<div class="visual-stage">${p3Grid(4,3)}</div>`;
 if(v==='gridAvoid')return `<div class="visual-stage">${p3Grid(2,2,null,{c:1,r:1})}</div>`;
 if(v==='grid4')return `<div class="visual-stage">${p3Grid(4,4)}</div>`;
 if(v==='gridCorner')return `<div class="visual-stage">${p3Grid(4,4,{c:0,r:0})}</div>`;
 if(v==='cutGrid')return `<div class="visual-stage">${cutGridSVG()}</div>`;
 if(v==='photo')return `<div class="visual-stage">${photoSVG()}</div>`;
 if(v==='triangle123537')return `<div class="visual-stage">${triangleSidesSVG()}</div>`;
 if(v==='frame')return `<div class="visual-stage">${frameSVG(false)}</div>`;
 if(v==='trianglePositions')return `<div class="visual-stage">${trianglePositionsSVG()}</div>`;
 if(v==='mixedOverlap')return `<div class="visual-stage">${overlapP3('80','56',state.lang==='en'?'union = 120':'gabungan = 120','80 cm²','56 cm²')}</div>`;
 if(v==='nested12')return `<div class="visual-stage">${nestedSquareSVG(12,10)}</div>`;
 if(v==='twoFold')return `<div class="visual-stage">${twoFoldSquareSVG()}</div>`;
 if(v==='stackRow')return `<div class="visual-stage">${stack6SVG('row')}</div>`;
 if(v==='moveTokens')return `<div class="visual-stage">${moveTokensSVG()}</div>`;
 if(v==='angle20')return angleChainSVG(20);
 if(v==='reshape18128')return `<div class="visual-stage">${reshapeP3SVG('18×12×8')}</div>`;
 if(v==='grid7')return `<div class="visual-stage">${p3Grid(7,7,{c:5,r:3})}</div>`;
 if(v==='frameFull')return `<div class="visual-stage">${frameSVG(true)}</div>`;
 if(v==='triangle12')return `<div class="visual-stage">${trianglePositionsSVG()}</div>`;
 return _phase2ProblemVisual(p)
};

function p3HintPanel(p){const step=state.p3HintStep[p.id]||0;if(step<=0)return '';let items=[];items.push(`<div class="hint-box"><strong>${t('guideLabel')}:</strong> ${esc(i18n(p.guide))}</div>`);for(let i=1;i<step;i++){const h=p.hints[i-1];if(h)items.push(`<div class="hint-box"><strong>${t('hintProgress')} ${i}:</strong> ${esc(i18n(h))}</div>`)}return items.join('')}
function p3EvidenceChip(id){const ev=p3Evidence(id);if(!ev)return '';return `<span class="evidence-chip ${ev}">${t(ev)}</span>`}
function p3MoveOnly(p){const chosen=state.p3SelectedMove[p.id]||'';const rationale=state.p3Rationale[p.id]||'';const fb=state.feedback[p.id];return `<div class="first-move-box"><label><strong>${t('firstMove')}</strong></label><div class="move-grid">${moveOptions.map(m=>`<button type="button" data-p3-move="${p.id}" data-move="${m.k}" class="${chosen===m.k?'chosen':''}"><b>${esc(state.lang==='en'?m.en:m.id)}</b></button>`).join('')}</div><label class="p3-rationale-label">${t('rationale')}</label><textarea data-p3-rationale="${p.id}">${esc(rationale)}</textarea><div class="answer-row"><button class="primary-btn" data-p3-check-move="${p.id}">${t('firstMoveCheck')}</button><button class="soft-btn" data-p3-hint="${p.id}">${t('hint')}</button></div>${p3HintPanel(p)}${fb?`<div class="feedback-box show ${fb.ok?'good':'bad'}">${fb.ok?(state.lang==='en'?'Strong first move.':'Langkah pertama yang kuat.'):(state.lang==='en'?'Choose a move that exposes structure and explain why it reduces work.':'Pilih langkah yang membuka struktur dan jelaskan mengapa pekerjaan menjadi lebih ringan.')} ${fb.ok?esc(i18n(p.transfer)):''}</div>`:''}${fb?.ok?`<div class="solution-box"><strong>${state.lang==='en'?'Why this move works:':'Mengapa langkah ini bekerja:'}</strong> ${esc(i18n(p.solution))}</div>`:''}</div>`}

renderProblem=function(p){
 const val=state.answers[p.id]||'',fb=state.feedback[p.id],move=state.moves[p.id]||'',step=state.p3HintStep[p.id]||0,sol=state.p3Solution[p.id];
 const targetRooms=['G','M','S'].includes(p.room);
 const strategyNote=targetRooms?'':`<span class="strategy-family">${esc(roomTitle(p.room))}</span>`;
 if(p.mode==='moveOnly')return `<div class="problem-card"><div class="problem-meta"><span>${p.id}</span><span class="level-${p.difficulty}">${p3LevelLabel(p)}</span><span>${p.time}</span>${p3EvidenceChip(p.id)}</div>${strategyNote}<p class="problem-q">${esc(i18n(p.q))}</p>${problemVisual(p)}${p3MoveOnly(p)}<div class="micro-actions"><button data-p3-change>${t('change')}</button><button data-p3-prev ${state.p3History.length?'':'disabled'}>${t('previousProblem')}</button></div><div class="teacher-panel teacher-only"><strong>${t('teacherNotes')}</strong><p>${t('source')}: ${esc(p.source)} · ${t('type')}: ${esc(p.type)}</p><p>${t('trap')}: ${esc(i18n(p.trap))}</p></div></div>`;
 return `<div class="problem-card"><div class="problem-meta"><span>${p.id}</span><span class="level-${p.difficulty}">${p3LevelLabel(p)}</span><span>${p.time}</span>${p3EvidenceChip(p.id)}</div>${strategyNote}<p class="problem-q">${esc(i18n(p.q))}</p>${problemVisual(p)}<div class="first-move-box"><label><strong>${t('firstMove')}</strong></label><textarea data-first-move="${p.id}" placeholder="${state.lang==='en'?'What would you change, mark, split, reflect, rebuild, or organize first?':'Apa yang akan kamu ubah, tandai, pecah, cerminkan, susun ulang, atau atur terlebih dahulu?'}">${esc(move)}</textarea></div><div class="workspace"><div class="answer-row"><input data-answer="${p.id}" value="${esc(val)}" placeholder="${state.lang==='en'?'Answer':'Jawaban'}"><button class="primary-btn" data-p3-check="${p.id}">${t('check')}</button><button class="soft-btn" data-p3-hint="${p.id}">${step===0?t('guideLabel'):`${t('hintProgress')} ${Math.min(step,3)}`}</button>${p.room==='M'?`<button class="ghost-btn" data-p3-skip="${p.id}">${t('skip')}</button>`:''}</div>${p3HintPanel(p)}${fb?`<div class="feedback-box show ${fb.ok?'good':'bad'}">${fb.ok?t('correct'):`${t('wrong')} ${esc(i18n(p.trap))}`}</div>`:''}${fb?.ok?`<div class="transfer-box"><strong>${state.lang==='en'?'Transfer:':'Bisa dipakai lagi:'}</strong> ${esc(i18n(p.transfer))}</div>`:''}${sol?`<div class="solution-box"><strong>${state.lang==='en'?'Complete solution:':'Solusi lengkap:'}</strong> ${esc(i18n(p.solution))}</div>`:''}<div class="micro-actions"><button data-p3-solution="${p.id}">${t('showSolution')}</button></div></div><div class="micro-actions"><button data-p3-change>${t('change')}</button><button data-p3-prev ${state.p3History.length?'':'disabled'}>${t('previousProblem')}</button></div><div class="teacher-panel teacher-only"><strong>${t('teacherNotes')}</strong><p>${t('source')}: ${esc(p.source)} · ${t('type')}: ${esc(p.type)} · ${t('time')}: ${esc(p.time)}</p><p>${t('trap')}: ${esc(i18n(p.trap))}</p></div></div>`
};

renderPractice=function(){
 const rooms=['A','B','C','D','E','F','G','M','S'];const p=currentProblem();const allSorted=[...bank].sort((a,b)=>a.id.localeCompare(b.id,undefined,{numeric:true}));
 return `<div class="page">${navHead(sections[10])}<div class="panel"><div class="label">${t('allProblems')}</div><p>${state.lang==='en'?'Rooms A–F train one visual family. Room G asks only for the first move. Mixed Visual Takes remove strategy labels. Stretch is optional. Every problem still begins with a first visual move.':'Ruang A–F melatih satu keluarga strategi visual. Ruang G hanya meminta langkah pertama. Latihan visual campuran menyembunyikan label strategi. Pengayaan bersifat opsional. Setiap soal tetap dimulai dengan langkah visual pertama.'}</p>${p3ProgressBar()}<div class="practice-nav">${rooms.map(r=>`<button class="${state.practiceRoom===r?'active':''}" data-room="${r}">${roomTitle(r)}</button>`).join('')}</div><div class="teacher-panel teacher-only p3-jump"><label>${t('teacherJump')}</label><select data-p3-jump><option value="">—</option>${allSorted.map(x=>`<option value="${x.id}" ${p&&x.id===p.id?'selected':''}>${x.id} · ${roomTitle(x.room)} · ${p3LevelLabel(x)}</option>`).join('')}</select></div>${!p?`<div class="feedback-box show">${t('noLevel')}</div>`:renderProblem(p)}</div>${navFoot()}</div>`
};

// Phase-3 event layer uses unique data attributes so verified Phase-2 handlers remain untouched.
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.p3Hint){const id=b.dataset.p3Hint,p=bank.find(x=>x.id===id);const cur=state.p3HintStep[id]||0;state.p3HintStep[id]=Math.min(4,cur+1);render();return}
 if(b.dataset.p3Check){const id=b.dataset.p3Check,p=bank.find(x=>x.id===id);const input=document.querySelector(`[data-answer="${id}"]`),mv=document.querySelector(`[data-first-move="${id}"]`);state.answers[id]=input?.value||'';state.moves[id]=mv?.value||state.moves[id]||'';if(!String(state.moves[id]).trim()){toast(t('firstMoveNeed'));return}state.p3Attempts[id]=(state.p3Attempts[id]||0)+1;const ok=answerOK(state.answers[id],p.answers);state.feedback[id]={ok};if(ok)p3RecordCorrect(p);render();return}
 if(b.dataset.p3Solution){const id=b.dataset.p3Solution;if(!(state.p3Attempts[id]>0||state.teacher)){toast(state.lang==='en'?'Try the problem once before opening the complete solution.':'Coba soal ini sekali sebelum membuka solusi lengkap.');return}state.p3Solution[id]=true;if(state.p3Solved[id])state.p3Solved[id].evidence='solutionSupported';render();return}
 if(b.dataset.p3Change!==undefined){const old=currentId(),pool=p3Pool();if(pool.length<2){toast(state.lang==='en'?'No other problem in this room and level.':'Tidak ada soal lain pada ruang dan level ini.');return}p3PushHistory(old);state.practiceIndex=(state.practiceIndex+1)%pool.length;render();return}
 if(b.dataset.p3Prev!==undefined){const h=state.p3History.pop();if(!h){toast(state.lang==='en'?'No previous problem yet.':'Belum ada soal sebelumnya.');return}const p=bank.find(x=>x.id===h.id);if(p){state.practiceRoom=p.room;state.level=h.level||state.level;const pool=p3Pool(p.room);state.practiceIndex=Math.max(0,pool.findIndex(x=>x.id===p.id));render()}return}
 if(b.dataset.p3Skip){state.p3Skipped[b.dataset.p3Skip]=true;const pool=p3Pool();p3PushHistory(currentId());state.practiceIndex=(state.practiceIndex+1)%pool.length;render();return}
 if(b.dataset.p3Move){state.p3SelectedMove[b.dataset.p3Move]=b.dataset.move;render();return}
 if(b.dataset.p3CheckMove){const id=b.dataset.p3CheckMove,p=bank.find(x=>x.id===id),chosen=state.p3SelectedMove[id],r=(state.p3Rationale[id]||'').trim();if(!chosen||!r){toast(state.lang==='en'?'Choose a first move and explain why it helps.':'Pilih langkah pertama dan jelaskan mengapa langkah itu membantu.');return}state.p3Attempts[id]=(state.p3Attempts[id]||0)+1;const ok=(p.goodMoves||[]).includes(chosen);state.feedback[id]={ok};if(ok)p3RecordCorrect(p);render();return}
},true);

document.addEventListener('input',e=>{if(e.target.dataset.p3Rationale)state.p3Rationale[e.target.dataset.p3Rationale]=e.target.value});
document.addEventListener('change',e=>{if(e.target.dataset.p3Jump!==undefined&&e.target.value)p3GoToId(e.target.value,true)});

// Keep history coherent when teacher/student changes room or level through the existing controls.
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if((b.dataset.room||b.matches('.level-btn'))&&state.section===10){const id=currentId();if(id)p3PushHistory(id)}},true);

render();
